#!/bin/bash
# Rebuilds visacards.html from the generated partials.
#
# The body is generated by _gen_visacards.py from the twenty-section
# specification, so every numbered sub-item (1.1 … 20.4) is present by
# construction and the figures stay consistent across sections.
set -e
cd "$(dirname "$0")"

python3 _gen_visacards.py
cat _visacards.css _visacards2.css > _visacards-build.css
python3 _compose.py _vchead.html visacards _visacards-build.css

{
  cat _vchead.html
  cat _vc2body.html
  cat _vc2js.js
  printf '</body>\n</html>\n'
} > visacards.html

python3 - <<'PY'
import pathlib
p = pathlib.Path('visacards.html')
s = p.read_text()
s = s.replace('<title>Module — GOLDEN FINANCIAL SERVICES</title>',
              '<title>VISA Card Management — GOLDEN FINANCIAL SERVICES</title>')
p.write_text(s)
print('built visacards.html', len(s), 'bytes')
PY

python3 inject_backnav.py visacards.html
